21	import SymbolDraw from '../../chart/helper/SymbolDraw';
22	import * as numberUtil from '../../util/number';
23	import SeriesData from '../../data/SeriesData';
24	import * as markerHelper from './markerHelper';
25	import MarkerView from './MarkerView';
