211	    const yPx = numberUtil.parsePercent(itemModel.get('y'), api.getHeight());
212	    if (!isNaN(xPx) && !isNaN(yPx)) {
213	        point = [xPx, yPx];
214	    }
215	    else {
216	        // Chart like bar may have there own marker positioning logic
217	        if (seriesModel.getMarkerPosition) {
