241	            const yAxis = coordSys.getAxis('y') as Axis2D;
242	            const dims = coordSys.dimensions;
243	            if (isInfinity(data.get(dims[0], idx))) {
244	                point[0] = xAxis.toGlobalCoord(xAxis.getExtent()[isFrom ? 0 : 1]);
