import { createChart, getViewGroup, getECModel } from '/workspace/test/ut/core/utHelper';
import Displayable from 'zrender/src/graphic/Displayable';

describe('marker z probe', function () {
    it('probe', function () {
        const chart = createChart();
        chart.setOption({
            animation: false,
            xAxis: { type: 'category', data: ['a', 'b', 'c'] },
            yAxis: {},
            series: [{
                type: 'line',
                data: [1, 2, 3],
                markPoint: { z: 42, data: [{ coord: ['b', 2] }] },
                markLine: { z: 43, data: [{ yAxis: 2 }] },
                markArea: { z: 44, data: [[{ xAxis: 'a' }, { xAxis: 'b' }]] }
            }]
        });
        const out: any = {};
        ['markPoint', 'markLine', 'markArea'].forEach(function (t) {
            const g = getViewGroup(chart, t as any);
            const zs: number[] = [];
            g && g.traverse(function (el) {
                if (!el.isGroup) {
                    zs.push((el as Displayable).z);
                }
            });
            out[t] = zs;
        });
        console.log(JSON.stringify(out));
        const mp = getECModel(chart).getComponent('markPoint');
        console.log('master markPoint z=', (mp as any).get('z'));
    });
});
